#include <stdio.h>
#include <stdlib.h>
#include <math.h>

typedef struct {
    double x, y, z, r;
} Sphere;

typedef struct {
    int u, v;
    double w;
} Edge;

static int cmp_edge(const void *a, const void *b) {
    double da = ((const Edge *)a)->w;
    double db = ((const Edge *)b)->w;
    if (da < db) return -1;
    if (da > db) return 1;
    return 0;
}

static int find_set(int *parent, int x) {
    if (parent[x] != x) parent[x] = find_set(parent, parent[x]);
    return parent[x];
}

static int union_set(int *parent, int *rank, int a, int b) {
    a = find_set(parent, a);
    b = find_set(parent, b);
    if (a == b) return 0;
    if (rank[a] < rank[b]) {
        parent[a] = b;
    } else if (rank[a] > rank[b]) {
        parent[b] = a;
    } else {
        parent[b] = a;
        rank[a]++;
    }
    return 1;
}

int main(void) {
    int n;
    while (scanf("%d", &n) == 1 && n) {
        Sphere *s = (Sphere *)malloc(sizeof(Sphere) * n);
        for (int i = 0; i < n; i++) {
            scanf("%lf %lf %lf %lf", &s[i].x, &s[i].y, &s[i].z, &s[i].r);
        }

        int m = n * (n - 1) / 2;
        Edge *edges = (Edge *)malloc(sizeof(Edge) * m);
        int idx = 0;

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                double dx = s[i].x - s[j].x;
                double dy = s[i].y - s[j].y;
                double dz = s[i].z - s[j].z;
                double dist = sqrt(dx * dx + dy * dy + dz * dz);
                double w = dist - s[i].r - s[j].r;
                if (w < 0) w = 0;
                edges[idx].u = i;
                edges[idx].v = j;
                edges[idx].w = w;
                idx++;
            }
        }

        qsort(edges, m, sizeof(Edge), cmp_edge);

        int *parent = (int *)malloc(sizeof(int) * n);
        int *rank = (int *)calloc(n, sizeof(int));
        for (int i = 0; i < n; i++) parent[i] = i;

        double ans = 0.0;
        int used = 0;
        for (int i = 0; i < m && used < n - 1; i++) {
            if (union_set(parent, rank, edges[i].u, edges[i].v)) {
                ans += edges[i].w;
                used++;
            }
        }

        printf("%.3f\n", ans);

        free(s);
        free(edges);
        free(parent);
        free(rank);
    }
    return 0;
}

