public class SpaceStation {
    static class Cell {
        double x, y, z, r;
        Cell(double x, double y, double z, double r) {
            this.x = x;
            this.y = y;
            this.z = z;
            this.r = r;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Cell[] cells = new Cell[n];
        for (int i = 0; i < n; i++) {
            double x = sc.nextDouble();
            double y = sc.nextDouble();
            double z = sc.nextDouble();
            double r = sc.nextDouble();
            cells[i] = new Cell(x, y, z, r);
        }
        sc.close();

        // Build adjacency matrix of distances
        double[][] dist = new double[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                double dx = cells[i].x - cells[j].x;
                double dy = cells[i].y - cells[j].y;
                double dz = cells[i].z - cells[j].z;
                double centerDist = Math.sqrt(dx * dx + dy * dy + dz * dz);
                double surfaceDist = centerDist - cells[i].r - cells[j].r;
                if (surfaceDist < 0) surfaceDist = 0;
                dist[i][j] = surfaceDist;
                dist[j][i] = surfaceDist;
            }
        }

        // Prim's algorithm for MST
        boolean[] visited = new boolean[n];
        double[] minEdge = new double[n];
        Arrays.fill(minEdge, Double.MAX_VALUE);
        minEdge[0] = 0;
        double total = 0;

        for (int i = 0; i < n; i++) {
            int u = -1;
            double best = Double.MAX_VALUE;
            for (int j = 0; j < n; j++) {
                if (!visited[j] && minEdge[j] < best) {
                    best = minEdge[j];
                    u = j;
                }
            }
            if (u == -1) break; // Should not happen for connected graph
            visited[u] = true;
            total += best;

            for (int v = 0; v < n; v++) {
                if (!visited[v] && dist[u][v] < minEdge[v]) {
                    minEdge[v] = dist[u][v];
                }
            }
        }

        System.out.printf("%.3f%n", total);
    }
}

