public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }

    static class Edge implements Comparable<Edge> {
        int u, v;
        double w;

        Edge(int u, int v, double w) {
            this.u = u;
            this.v = v;
            this.w = w;
        }

        public int compareTo(Edge other) {
            return Double.compare(this.w, other.w);
        }
    }

    static class DSU {
        int[] p, r;

        DSU(int n) {
            p = new int[n];
            r = new int[n];
            for (int i = 0; i < n; i++) p[i] = i;
        }

        int find(int x) {
            if (p[x] != x) p[x] = find(p[x]);
            return p[x];
        }

        boolean union(int a, int b) {
            int ra = find(a), rb = find(b);
            if (ra == rb) return false;
            if (r[ra] < r[rb]) p[ra] = rb;
            else if (r[ra] > r[rb]) p[rb] = ra;
            else {
                p[rb] = ra;
                r[ra]++;
            }
            return true;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        String first = fs.next();
        if (first == null) return;

        StringBuilder out = new StringBuilder();

        while (true) {
            int n = Integer.parseInt(first);
            if (n == 0) break;

            double[] x = new double[n];
            double[] y = new double[n];
            double[] z = new double[n];
            double[] r = new double[n];

            for (int i = 0; i < n; i++) {
                x[i] = fs.nextDouble();
                y[i] = fs.nextDouble();
                z[i] = fs.nextDouble();
                r[i] = fs.nextDouble();
            }

            List<Edge> edges = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                for (int j = i + 1; j < n; j++) {
                    double dx = x[i] - x[j];
                    double dy = y[i] - y[j];
                    double dz = z[i] - z[j];
                    double dist = Math.sqrt(dx * dx + dy * dy + dz * dz) - r[i] - r[j];
                    if (dist < 0) dist = 0;
                    edges.add(new Edge(i, j, dist));
                }
            }

            Collections.sort(edges);
            DSU dsu = new DSU(n);
            double ans = 0.0;
            int used = 0;

            for (Edge e : edges) {
                if (dsu.union(e.u, e.v)) {
                    ans += e.w;
                    used++;
                    if (used == n - 1) break;
                }
            }

            out.append(String.format(Locale.US, "%.3f%n", ans));
            first = fs.next();
            if (first == null) break;
        }

        System.out.print(out.toString());
    }
}

import sys
import math


def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    out = []

    while True:
        try:
            n = int(next(it))
        except StopIteration:
            break

        if n == 0:
            break

        spheres = []
        for _ in range(n):
            x = float(next(it))
            y = float(next(it))
            z = float(next(it))
            r = float(next(it))
            spheres.append((x, y, z, r))

        # Build all edges with weight = max(0, distance between centers - r1 - r2)
        edges = []
        for i in range(n):
            x1, y1, z1, r1 = spheres[i]
            for j in range(i + 1, n):
                x2, y2, z2, r2 = spheres[j]
                dx = x1 - x2
                dy = y1 - y2
                dz = z1 - z2
                d = math.sqrt(dx * dx + dy * dy + dz * dz) - r1 - r2
                if d < 0:
                    d = 0.0
                edges.append((d, i, j))

        # Kruskal's MST
        edges.sort()

        parent = list(range(n))
        rank = [0] * n

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a, b):
            ra = find(a)
            rb = find(b)
            if ra == rb:
                return False
            if rank[ra] < rank[rb]:
                parent[ra] = rb
            elif rank[ra] > rank[rb]:
                parent[rb] = ra
            else:
                parent[rb] = ra
                rank[ra] += 1
            return True

        total = 0.0
        used = 0
        for w, u, v in edges:
            if union(u, v):
                total += w
                used += 1
                if used == n - 1:
                    break

        out.append(f"{total:.3f}")

    sys.stdout.write("\n".join(out))


if __name__ == "__main__":
    solve()
